package com.example.quanlykhohang;
import android.os.Bundle; import android.app.AlertDialog; import android.widget.TextView; import android.graphics.Color;
public class ProductDetailActivity extends BaseActivity {
 private int id; private Product p;
 protected void onCreate(Bundle b){super.onCreate(b);screen(R.layout.activity_product_detail);id=getIntent().getIntExtra("id",-1);if(!refresh())return;findViewById(R.id.back).setOnClickListener(v->finish());findViewById(R.id.plus).setOnClickListener(v->{if(p.quantity==Integer.MAX_VALUE){toast("Đã đạt số lượng tối đa");return;}change(p.quantity+1);});findViewById(R.id.minus).setOnClickListener(v->{if(p.quantity==0)toast("Hết hàng");else change(p.quantity-1);});findViewById(R.id.delete).setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Xóa sản phẩm?").setMessage(p.name).setNegativeButton("Hủy",null).setPositiveButton("Xóa",(dialog,w)->{if(db.deleteProduct(id)>0){toast("Đã xóa sản phẩm");finish();}else toast("Không thể xóa");}).show());}
 private void change(int q){if(db.updateQuantity(id,q)>0)refresh();else toast("Không thể cập nhật");}
 private boolean refresh(){p=db.getProductById(id);if(p==null){toast("Không tìm thấy sản phẩm");finish();return false;}text(R.id.detailName,p.name);text(R.id.detailCategory,p.category+" • "+(p.active?"Đang kinh doanh":"Ngừng kinh doanh"));text(R.id.detailPrice,Product.money(p.price));text(R.id.detailQuantity,"Số lượng tồn: "+p.quantity+(p.quantity<5?"  •  Sắp hết hàng":""));((TextView)findViewById(R.id.detailQuantity)).setTextColor(Color.parseColor(p.quantity<5?"#C62828":"#20332F"));text(R.id.detailValue,"Giá trị tồn kho: "+Product.money((long)p.price*p.quantity));text(R.id.detailDescription,p.description==null||p.description.isEmpty()?"Không có mô tả":p.description);return true;}
}